Calling [distance matrix API](https://qdrant.tech/documentation/concepts/explore/?q=distance+#distance-matrix) once per cluster. 

`sample` - how many points we are sampling (here filtered by `crop_name` field, so we are sampling within each cluster, and since we are passing the biggest cluster size to `sample`, we will get all points from each cluster.

`limit` is the number of neighbours distance to which we will see calculated. Since we want all pairwise distances between the points within a cluster, here we're once again setting an upper limit equal to the biggest cluster size;

// Retrieve the CSV-like data from the 'data' field in the input
const csvData = $json['data']; // Ensure that 'data' is the correct field name

// Check if csvData exists and is not empty
if (!csvData) {
  console.log("Input data structure:", $json); // Debugging output to inspect input structure
  throw new Error('No CSV data provided. Ensure the correct field reference is being used.');
}

// Split the CSV into rows
const rows = csvData.split('\n');

// Extract the headers
const headers = rows[0].replace(/"/g, '').split(',');

// Iterate over each data row and map it to an object
const output = rows.slice(1).map(row => {
  const values = row.match(/(".*?"|[^",]+)(?=\s*,|\s*$)/g).map(value => {
    // Remove surrounding quotes from each value if present
    return value.startsWith('"') && value.endsWith('"') ? value.slice(1, -1) : value;
  });

  const item = {};
  headers.forEach((header, index) => {
    item[header] = values[index] || null;
  });

  return { json: item };
});

return output;

